import React, { useEffect } from "react";
import TopNewNav from "../../moleculars/TopNewNav";
import { useLocation, useParams } from "react-router-dom";
import PaddingPwa from "../../moleculars/PaddingPwa";
import HeaderCheckoutLayanan from "../../moleculars/HeaderCheckoutLayanan";
import { getNameLayanan } from "../../utils/layananService";
import ContentDetailCheckout from "../../moleculars/ContentDetailCheckout";
import ButtonComponent from "../../atoms/ButtonComponent";
import CheckoutValue from "../../moleculars/CheckoutValue";
import Gap from "../../moleculars/Gap";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { paymentGadaPratama, pengurusanRingkasanList } from "../../../redux/action/paymentAction";

function RingkasanPengurusan() {

    const params = useParams()
    const dispatch = useDispatch()
    const location = useLocation()
    const currentPath = location.pathname
    const segment = currentPath.split("/")[2]
    const storeData = useSelector((store) => store?.global);
    const { detail_data_layanan } = storeData;

    useEffect(() => {
        getDataPengurusan()
    }, [])

    const getDataPengurusan = async () => {
        dispatch(await pengurusanRingkasanList(params?.id));
    }

    const formik = useFormik({
        enableReinitialize: true,
        initialValues: {
            order_id: params?.id,
        },
        onSubmit: async (values) => {
            
            dispatch(await paymentGadaPratama(values));
        },
    });

    const renderButton = () => {
        if (detail_data_layanan?.detail?.detail?.payment_status === "ORDER") {
            return (
                <ButtonComponent
                    typeButton="rincian"
                    others={
                        <CheckoutValue
                            title="Total Pembayaran"
                            value={detail_data_layanan?.detail?.detail?.order_total}
                            color="var(--font-color10)"
                            number={true}
                        />
                    }
                    title="Bayar Sekarang "
                    type="submit"
                />
            );
        } else if (detail_data_layanan?.detail?.detail?.payment_status === "UNPAID") {
            return (
                <ButtonComponent
                    typeButton="rincian"
                    others={
                        <CheckoutValue
                            title="Total Pembayaran"
                            value={detail_data_layanan?.detail?.detail?.order_total}
                            color="var(--font-color10)"
                            number={true}
                        />
                    }
                    border="#fef5e8"
                    background="#fef5e8"
                    color="#f99f1b"
                    title="Klik untuk membayar"
                    type="button"
                    onClick={() =>
                        (window.location = `${process.env.REACT_APP_API_INVOICE_URL}${detail_data_layanan?.detail?.invoice_id}`)
                    }
                />
            );
        } else if (detail_data_layanan?.detail?.detail?.payment_status === "EXPIRED") {
            return (
                <ButtonComponent
                    typeButton="rincian"
                    others={
                        <CheckoutValue
                            title="Total Pembayaran"
                            value={detail_data_layanan?.detail?.detail?.order_total}
                            color="var(--font-color10)"
                            number={true}
                        />
                    }
                    background="var(--font-color11)"
                    color="var(--bg-color7)"
                    border="var(--font-color11)"
                    title="Sudah Dibayar"
                    type="button"
                //   onClick={() => navigate(`/account/profile/change/${id}`)}
                />
            );
        } else {
            return (
                <ButtonComponent
                    typeButton="rincian"
                    others={
                        <CheckoutValue
                            title="Total Pembayaran"
                            value={detail_data_layanan?.detail?.order_total}
                            color="var(--font-color10)"
                            number={true}
                        />
                    }
                    border="var(--font-color12)"
                    background="var(--font-color12)"
                    color="var(--bg-color2)"
                    title="Sudah Dibayar"
                    type="button"
                //   onClick={() => navigate(`/account/profile/change/${id}`)}
                />
            );
        }
    };

    return (
        <>
            <TopNewNav title={`Ringkasan ${(detail_data_layanan?.detail?.detail?.tnos_service_id === "6" && detail_data_layanan?.detail?.detail?.tnos_subservice_id === "2") ? "Pembuatan Baru" : (detail_data_layanan?.detail?.detail?.tnos_service_id === "6" && detail_data_layanan?.detail?.detail?.tnos_subservice_id === "3") ? "Perpanjangan" : ""}`} path={`/pengurusan-gada-pratama/${segment === "pembuatan-baru" ? "pembuatan-baru" : segment === "perpanjangan" ? "perpanjangan" : ""}`} />
            <div className="container-class">
                <div className="responsive-class">
                    <div className="res-class">
                        <div
                            className="dashboard-container-f"
                            style={{ marginTop: "60px" }}
                        >
                            <PaddingPwa padding={15}>
                                <HeaderCheckoutLayanan
                                    layanan={getNameLayanan(
                                        "6",
                                        detail_data_layanan?.detail?.detail?.tnos_subservice_id
                                    )}
                                // layanan={getNameLayanan(
                                //      detail_data_layanan?.detail?.tnos_service_id,
                                //     detail_data_layanan?.detail?.tnos_subservice_id
                                // )}
                                // payment_status={detail_data_layanan?.detail?.payment_status}
                                />
                                <ContentDetailCheckout
                                    layanan={getNameLayanan(
                                        "6",
                                        detail_data_layanan?.detail?.detail?.tnos_subservice_id
                                    )}
                                    data={detail_data_layanan?.detail?.detail}
                                />
                                {/* <ContentDetailCheckout
                                    layanan={getNameLayanan(
                                        detail_data_layanan?.detail?.tnos_service_id,
                                        detail_data_layanan?.detail?.tnos_subservice_id
                                    )}
                                    data={detail_data_layanan?.detail}
                                /> */}
                            </PaddingPwa>
                            <Gap height={120} />
                            <form action="" onSubmit={formik.handleSubmit}>
                                {renderButton()}
                            </form>
                        </div>
                    </div>
                </div>
            </div>
        </>
    )
}

export default RingkasanPengurusan